/// A simple random-bit generator structure.
#[derive(Debug, Clone)]
struct Generator {
    /// Whether the generator has been initialized.
    initialized: bool,
    /// The optional 64-bit seed provided by the user.
    seed: Option<u64>,
    /// The internal 64-bit state derived from `seed`.
    state: u64,
}

/// Computes an internal state from an optional 64-bit seed.
///
/// If `seed` is `Some(s)`:
///   - and `s != 0`, returns `s` unchanged (non-zero).
///   - and `s == 0`, returns `1` to guarantee a non-zero state.
/// If `seed` is `None`, returns `0`.
fn compute_state(seed: Option<u64>) -> u64 {
    match seed {
        Some(s) if s != 0 => s,
        Some(_)             => 1,
        None                => 0,
    }
}

/// Constructs a `Generator` initialized from an optional 64-bit seed.
///
/// - The returned generator has `initialized = true`.
/// - Its `seed` field is exactly the input `seed`.
/// - Its `state` field is derived via `compute_state(seed)`.
fn default_rng(seed: Option<u64>) -> Generator {
    let state = compute_state(seed);
    Generator {
        initialized: true,
        seed,
        state,
    }
}

// Example usage
fn main() {
    let g1 = default_rng(Some(42));
    println!("With seed=42: {:?}", g1);
    assert!(g1.initialized);
    assert_eq!(g1.seed, Some(42));
    assert_eq!(g1.state, 42);

    let g2 = default_rng(Some(0));
    println!("With seed=0:  {:?}", g2);
    assert!(g2.initialized);
    assert_eq!(g2.seed, Some(0));
    assert_eq!(g2.state, 1);

    let g3 = default_rng(None);
    println!("With seed=None: {:?}", g3);
    assert!(g3.initialized);
    assert_eq!(g3.seed, None);
    assert_eq!(g3.state, 0);
}